import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Anti-XSS filter - does NOT protect against SQL injection
    private String sanitizeOutput(String input) {
        if (input == null) return null;
        return input.replace("<", "&lt;").replace(">", "&gt;")
                    .replace("\"", "&quot;").replace("'", "&#x27;");
    }

    // Audit logging with prepared statement (safe)
    private void logAccess(Connection conn, String user, String action) throws SQLException {
        PreparedStatement ps = conn.prepareStatement(
            "INSERT INTO audit_log (username, action, ts) VALUES (?, ?, NOW())");
        ps.setString(1, user);
        ps.setString(2, action);
        ps.executeUpdate();
        ps.close();
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setContentType("application/json");
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String sessionUser = (String) req.getSession().getAttribute("username");

        if (sessionUser == null) {
            resp.setStatus(401);
            resp.getWriter().write("{\"error\":\"unauthorized\"}");
            return;
        }

        // Validate reportType against whitelist
        if (!Pattern.matches("^(sales|inventory|users|financial)$", reportType != null ? reportType : "")) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"invalid report type\"}");
            return;
        }

        // Validate dateRange format
        if (dateRange != null && !Pattern.matches("^\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}$", dateRange)) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"invalid date range format\"}");
            return;
        }

        // sortCol is used directly in ORDER BY - cannot be parameterized
        // Developer note: "validated on frontend, backend trusts it"
        if (sortCol == null || sortCol.isEmpty()) {
            sortCol = "created_at";
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            logAccess(conn, sessionUser, "view_report_" + reportType);

            String[] dates = dateRange.split("_");
            // The ORDER BY clause is vulnerable to SQL injection
            String query = "SELECT id, name, amount, created_at FROM report_" + reportType +
                          " WHERE created_at BETWEEN ? AND ?" +
                          " AND tenant_id = ?" +
                          " ORDER BY " + sortCol + " LIMIT 500";

            PreparedStatement ps = conn.prepareStatement(query);
            ps.setString(1, dates[0]);
            ps.setString(2, dates[1]);
            ps.setInt(3, getTenantId(sessionUser));

            ResultSet rs = ps.executeQuery();
            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getInt("id"));
                row.put("name", sanitizeOutput(rs.getString("name")));
                row.put("amount", rs.getDouble("amount"));
                row.put("created_at", rs.getString("created_at"));
                results.put(row);
            }
            rs.close();
            ps.close();

            JSONObject response = new JSONObject();
            response.put("data", results);
            response.put("count", results.length());
            resp.getWriter().write(response.toString());
        } catch (SQLException e) {
            resp.setStatus(500);
            // Error message does not leak SQL details
            resp.getWriter().write("{\"error\":\"internal error\"}");
        }
    }

    private int getTenantId(String username) {
        // Stub: returns tenant from session cache
        return 1;
    }
}
